  // requested mid-flight (requested vs the level actually running).
  thinkLevel?: string;
  configuredBudget?: number;
  thinkingChars?: number;
  hadRealThinking?: boolean;
  redacted?: boolean;
  outputTokens?: number;
  numTurns?: number;
